import{_ as a,o as e,c as l,ao as t}from"./chunks/framework.BVf1Yn4g.js";const g=JSON.parse('{"title":"Usage","description":"","frontmatter":{},"headers":[],"relativePath":"usage.md","filePath":"usage.md","lastUpdated":null}'),s={name:"usage.md"};function r(o,i,d,n,p,h){return e(),l("div",null,[...i[0]||(i[0]=[t(`<h1 id="Usage" tabindex="-1">Usage <a class="header-anchor" href="#Usage" aria-label="Permalink to &quot;Usage {#Usage}&quot;">​</a></h1><h2 id="Multi-GPU-with-three-functions" tabindex="-1">Multi-GPU with three functions <a class="header-anchor" href="#Multi-GPU-with-three-functions" aria-label="Permalink to &quot;Multi-GPU with three functions {#Multi-GPU-with-three-functions}&quot;">​</a></h2><p>Only three functions are required to perform halo updates close to hardware limit:</p><ul><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.init_global_grid"><code>init_global_grid</code></a></p></li><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.update_halo!"><code>update_halo!</code></a></p></li><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.finalize_global_grid"><code>finalize_global_grid</code></a></p></li></ul><p>Three additional functions are provided to query Cartesian coordinates with respect to the global computational grid if required:</p><ul><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.x_g"><code>x_g</code></a></p></li><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.y_g"><code>y_g</code></a></p></li><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.z_g"><code>z_g</code></a></p></li></ul><p>Moreover, the following three functions allow to query the size of the global grid:</p><ul><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.nx_g"><code>nx_g</code></a></p></li><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.ny_g"><code>ny_g</code></a></p></li><li><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.nz_g"><code>nz_g</code></a></p></li></ul><p>The <a href="/ImplicitGlobalGrid.jl/previews/PR134/examples/diffusion3D_multigpu_CuArrays_novis#example-50-lines">50-lines Multi-GPU example</a> illustrates how these functions enable the creation of massively parallel applications.</p><p>Further tools: global indices (<a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.ix_g"><code>ix_g</code></a>, <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.iy_g"><code>iy_g</code></a>, <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.iz_g"><code>iz_g</code></a>), local and global extents of arrays, e.g. for parallel VTK output (<a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.extents"><code>extents</code></a>, <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.extents_g"><code>extents_g</code></a>, <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.metagrid"><code>metagrid</code></a>) and timing (<a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.tic"><code>tic</code></a>, <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.toc"><code>toc</code></a>).</p><h2 id="GPU-support-and-device-selection" tabindex="-1">GPU support and device selection <a class="header-anchor" href="#GPU-support-and-device-selection" aria-label="Permalink to &quot;GPU support and device selection {#GPU-support-and-device-selection}&quot;">​</a></h2><p>Support for Nvidia or AMD GPUs is activated by importing <a href="https://github.com/JuliaGPU/CUDA.jl" target="_blank" rel="noreferrer">CUDA.jl</a> or <a href="https://github.com/JuliaGPU/AMDGPU.jl" target="_blank" rel="noreferrer">AMDGPU.jl</a> before ImplicitGlobalGrid:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-LDmpf" id="tab-XFbsQcD" checked><label data-title="CPUs" for="tab-XFbsQcD">CPUs</label><input type="radio" name="group-LDmpf" id="tab-MTqnvJt"><label data-title="Nvidia GPUs" for="tab-MTqnvJt">Nvidia GPUs</label><input type="radio" name="group-LDmpf" id="tab-rreHD6y"><label data-title="AMD GPUs" for="tab-rreHD6y">AMD GPUs</label></div><div class="blocks"><div class="language-julia vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ImplicitGlobalGrid</span></span></code></pre></div><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CUDA</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ImplicitGlobalGrid</span></span></code></pre></div><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AMDGPU</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ImplicitGlobalGrid</span></span></code></pre></div></div></div><p>By default, <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.init_global_grid"><code>init_global_grid</code></a> selects the GPU corresponding to the node-local MPI rank (see <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.select_device"><code>select_device</code></a>); every rank must then see all GPUs of its node. If the job launcher already binds one GPU per rank (e.g. Slurm <code>--gpus-per-task=1</code>), set <code>select_device=false</code>. To run on CPUs only while a GPU package is loaded, set <code>device_type=&quot;none&quot;</code>.</p><h2 id="CUDA-/ROCm-aware-MPI-support" tabindex="-1">CUDA-/ROCm-aware MPI support <a class="header-anchor" href="#CUDA-/ROCm-aware-MPI-support" aria-label="Permalink to &quot;CUDA-/ROCm-aware MPI support {#CUDA-/ROCm-aware-MPI-support}&quot;">​</a></h2><p>If the system supports CUDA-aware MPI (for Nvidia GPUs) or ROCm-aware MPI (for AMD GPUs), it can be activated for ImplicitGlobalGrid by setting the following environment variable (at latest before the call to <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.init_global_grid"><code>init_global_grid</code></a>):</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-2TSrR" id="tab-1K9VgJn" checked><label data-title="Nvidia GPUs" for="tab-1K9VgJn">Nvidia GPUs</label><input type="radio" name="group-2TSrR" id="tab-GPJtSo6"><label data-title="AMD GPUs" for="tab-GPJtSo6">AMD GPUs</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IGG_CUDAAWARE_MPI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IGG_ROCMAWARE_MPI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div></div></div><p>It can also be activated per dimension, see <a href="/ImplicitGlobalGrid.jl/previews/PR134/usage#Environment-variables">Environment variables</a>.</p><h2 id="Multi-threaded-CPU-halo-copies" tabindex="-1">Multi-threaded CPU halo copies <a class="header-anchor" href="#Multi-threaded-CPU-halo-copies" aria-label="Permalink to &quot;Multi-threaded CPU halo copies {#Multi-threaded-CPU-halo-copies}&quot;">​</a></h2><p>Halo copies of CPU arrays can be multi-threaded with <a href="https://github.com/JuliaSIMD/Polyester.jl" target="_blank" rel="noreferrer">Polyester.jl</a> by importing it before ImplicitGlobalGrid, setting <code>IGG_USE_POLYESTER=1</code> and starting Julia with multiple threads (e.g. <code>julia -t 4</code>):</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Polyester</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ImplicitGlobalGrid</span></span></code></pre></div><h2 id="CellArrays" tabindex="-1">CellArrays <a class="header-anchor" href="#CellArrays" aria-label="Permalink to &quot;CellArrays {#CellArrays}&quot;">​</a></h2><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.update_halo!"><code>update_halo!</code></a> also accepts <code>CellArray</code>s of <a href="https://github.com/omlins/CellArrays.jl" target="_blank" rel="noreferrer">CellArrays.jl</a> (with blocklength <code>0</code> or <code>1</code>).</p><h2 id="Multiple-grids" tabindex="-1">Multiple grids <a class="header-anchor" href="#Multiple-grids" aria-label="Permalink to &quot;Multiple grids {#Multiple-grids}&quot;">​</a></h2><p><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.init_global_grid"><code>init_global_grid</code></a> creates and activates one grid. Additional grids are created with <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.create_global_grid"><code>create_global_grid</code></a> and selected with <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.activate_global_grid"><code>activate_global_grid</code></a> (or passed to <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.update_halo!"><code>update_halo!</code></a> with the keyword <code>active_global_grid</code>); <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.get_global_grid"><code>get_global_grid</code></a> returns the active grid:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">init_global_grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()                          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Initialize the package without creating a grid.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gg1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> create_global_grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nx, ny, nz)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gg2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> create_global_grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nx, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ny, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nz)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">activate_global_grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(gg1)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">update_halo!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(A1)                            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Uses gg1.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">update_halo!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(A2; active_global_grid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gg2)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Uses gg2.</span></span></code></pre></div><h2 id="in-situ-usage" tabindex="-1">In-situ visualization / monitoring <a class="header-anchor" href="#in-situ-usage" aria-label="Permalink to &quot;In-situ visualization / monitoring {#in-situ-usage}&quot;">​</a></h2><p>ImplicitGlobalGrid provides a function to gather an array from each process into a one large array on a single process, assembled according to the global grid:</p><ul><li><a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.gather!"><code>gather!</code></a></li></ul><p>This enables straightforward in-situ visualization or monitoring of Multi-GPU/CPU applications as shown in <a href="/ImplicitGlobalGrid.jl/previews/PR134/examples/diffusion3D_multigpu_CuArrays_onlyvis#in-situ-example">this example</a>.</p><h2 id="Seamless-interoperability-with-MPI.jl" tabindex="-1">Seamless interoperability with MPI.jl <a class="header-anchor" href="#Seamless-interoperability-with-MPI.jl" aria-label="Permalink to &quot;Seamless interoperability with MPI.jl {#Seamless-interoperability-with-MPI.jl}&quot;">​</a></h2><p>ImplicitGlobalGrid is seamlessly interoperable with <a href="https://github.com/JuliaParallel/MPI.jl" target="_blank" rel="noreferrer">MPI.jl</a>. The Cartesian MPI communicator it uses is created by default when calling <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.init_global_grid"><code>init_global_grid</code></a> and can then be obtained as follows (variable <code>comm_cart</code>):</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">me, dims, nprocs, coords, comm_cart </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> init_global_grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nx, ny, nz);</span></span></code></pre></div><p>Moreover, the automatic initialization and finalization of MPI can be deactivated in order to replace them with direct calls to <a href="https://github.com/JuliaParallel/MPI.jl" target="_blank" rel="noreferrer">MPI.jl</a>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">init_global_grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nx, ny, nz; init_MPI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">finalize_global_grid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(;finalize_MPI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Besides, <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.init_global_grid"><code>init_global_grid</code></a> makes every argument it passes to an <a href="https://github.com/JuliaParallel/MPI.jl" target="_blank" rel="noreferrer">MPI.jl</a> function customizable via its keyword arguments.</p><h2 id="Environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#Environment-variables" aria-label="Permalink to &quot;Environment variables {#Environment-variables}&quot;">​</a></h2><p>The following environment variables are read when a grid is created (<a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.init_global_grid"><code>init_global_grid</code></a> or <a href="/ImplicitGlobalGrid.jl/previews/PR134/api#ImplicitGlobalGrid.create_global_grid"><code>create_global_grid</code></a>); a value <code>&gt; 0</code> activates the feature:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>IGG_CUDAAWARE_MPI</code></td><td style="text-align:left;">Use CUDA-aware MPI in all dimensions.</td></tr><tr><td style="text-align:left;"><code>IGG_CUDAAWARE_MPI_DIMX</code>, <code>IGG_CUDAAWARE_MPI_DIMY</code>, <code>IGG_CUDAAWARE_MPI_DIMZ</code></td><td style="text-align:left;">Use CUDA-aware MPI in the given dimension (only read if <code>IGG_CUDAAWARE_MPI</code> is not activated).</td></tr><tr><td style="text-align:left;"><code>IGG_ROCMAWARE_MPI</code></td><td style="text-align:left;">Use ROCm-aware MPI in all dimensions.</td></tr><tr><td style="text-align:left;"><code>IGG_ROCMAWARE_MPI_DIMX</code>, <code>IGG_ROCMAWARE_MPI_DIMY</code>, <code>IGG_ROCMAWARE_MPI_DIMZ</code></td><td style="text-align:left;">Use ROCm-aware MPI in the given dimension (only read if <code>IGG_ROCMAWARE_MPI</code> is not activated).</td></tr><tr><td style="text-align:left;"><code>IGG_USE_POLYESTER</code></td><td style="text-align:left;">Use Polyester for the CPU halo copies in all dimensions (requires importing Polyester).</td></tr><tr><td style="text-align:left;"><code>IGG_USE_POLYESTER_DIMX</code>, <code>IGG_USE_POLYESTER_DIMY</code>, <code>IGG_USE_POLYESTER_DIMZ</code></td><td style="text-align:left;">Override <code>IGG_USE_POLYESTER</code> in the given dimension (only read if <code>IGG_USE_POLYESTER</code> is activated).</td></tr></tbody></table>`,40)])])}const b=a(s,[["render",r]]);export{g as __pageData,b as default};
